import React from 'react';
import { useOutletContext } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';

const Cloud_P4 = () => {
  const context = useOutletContext();
  const { data: cloudData, setter: setCloudData } = context?.cloud || {};
  const resumeData = Array.isArray(context) ? context[0] : context?.resumeData;

  return (
    <div className="workspace-container">
      <ProjectNavbar basePath="cloud" links={["Clusters", "VPC", "Balancers", "Telemetry"]} />
      <div className="summary-box">
        <h3>Cloud Provider Edge Telemetry Consolidation</h3>
        <pre style={{ backgroundColor: '#020617', color: '#a7f3d0', padding: '1rem', marginTop: '1rem', borderRadius: '4px', fontStyle: 'normal' }}>
          {resumeData ? JSON.stringify({ core: "CLOUD_METRICS_LEDGER", tracking_delay: `${resumeData.latency || 0}ms`, status: "HEALTHY" }, null, 2) : "> Network trace diagnostic interface offline. Drop packet telemetry engine standby."}
        </pre>
      </div>
    </div>
  );
};
export default Cloud_P4;
